import React from 'react'
import './WeatherApp.css'
import search_icon from "..Assets/search.png";
import clear_icon from "..Assets/clear.png";
import cloud_icon from "../Assets/cloud.png";
import drizzle_icon from "../Assets/drizzle.png";
import humidity_icon from "../src/Components/Assets/humidity.png";
import rain_icon from "../src/Components/Assets/rain.png";
import snow_icon from "../src/Components/Assets/snow.png";
import wind_icon from "../src/Components/Assets/wind.png";
const WeatherApp = () => {
  return (
    <div className="container">
    <div className='top-bar'>
      <input type='text' placeholder='Search' className='cityInput'></input>
      <div className='search-icon'>
        <img src={search_icon} alt='search' />
      </div>
    </div>
  </div>
  )
}

export default WeatherApp
